/**
 * Apply fixed logos and application links to Supabase + TS data files
 * Uses the fixed_programs.json generated by fix-broken-links.py
 */

const fs = require('fs');
const path = require('path');
const { createClient } = require('@supabase/supabase-js');
require('dotenv').config({ path: '.env.local' });

const fixedPrograms = JSON.parse(
  fs.readFileSync(
    '/Users/raviteja/.gemini/antigravity-ide/brain/faeb3fb4-dc57-4fad-a75d-c66bbeacc50d/scratch/fixed_programs.json',
    'utf8'
  )
);

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function applyFixes() {
  console.log(`Applying fixes for ${fixedPrograms.length} programs...\n`);

  let successCount = 0;
  let errorCount = 0;

  // Batch upsert by category to TS files
  const configs = [
    {
      filePath: path.join(__dirname, '..', 'data', 'accelerators-2026.ts'),
      varName: 'accelerators2026',
      typeName: 'Accelerator',
      category: 'accelerators'
    },
    {
      filePath: path.join(__dirname, '..', 'data', 'incubators-2026.ts'),
      varName: 'incubators2026',
      typeName: 'Incubator',
      category: 'incubators'
    },
    {
      filePath: path.join(__dirname, '..', 'data', 'grants-2026.ts'),
      varName: 'grants2026',
      typeName: 'Grant',
      category: 'grants'
    }
  ];

  // Update TS data files
  for (const cfg of configs) {
    const catPrograms = fixedPrograms.filter(p => p.category === cfg.category);
    const content = `export interface ${cfg.typeName} {
  id: string;
  name: string;
  slug: string;
  logo?: string;
  location: string;
  region: string;
  investment: string;
  equity: string;
  focusArea: string;
  founderStage: string;
  programDuration: string;
  applicationDeadline?: string;
  applicationStatus: 'Active' | 'Rolling' | 'Closed' | 'Opening Soon' | 'Invite Only';
  website: string;
  applicationLink: string;
  description: string;
  features?: string[];
}

export const ${cfg.varName}: ${cfg.typeName}[] = ${JSON.stringify(catPrograms, null, 2)};
`;
    fs.writeFileSync(cfg.filePath, content, 'utf8');
    console.log(`✅ Updated TS file: ${cfg.filePath} (${catPrograms.length} records)`);
  }

  // Update Supabase in batches of 50
  console.log('\nUpdating Supabase...');
  const batchSize = 50;
  for (let i = 0; i < fixedPrograms.length; i += batchSize) {
    const batch = fixedPrograms.slice(i, i + batchSize);
    const dbRows = batch.map(p => ({
      slug: p.slug,
      title: p.name,
      provider: p.name,
      category: 'startup-programs',
      subcategory: p.category,
      description: p.description,
      short_description: p.description.substring(0, 150),
      value: p.investment,
      application_url: p.applicationLink,
      logo_url: p.logo,
      provider_website: p.website,
      status: 'active',
      eligibility: [p.founderStage],
      requirements: ['Early Stage Startup'],
      application_process: ['Visit website to apply'],
      source_verified: true,
      data_source: 'import',
      featured: false,
      recommended: false,
      verified: true,
      difficulty: 'medium',
      time_to_apply: 'Varies',
      tags: p.features || []
    }));

    const { error } = await supabase
      .from('deals')
      .upsert(dbRows, { onConflict: 'slug' });

    if (error) {
      console.error(`  ❌ Batch ${i}-${i + batchSize}: ${error.message}`);
      errorCount += batch.length;
    } else {
      console.log(`  ✅ Batch ${i + 1}-${Math.min(i + batchSize, fixedPrograms.length)} upserted`);
      successCount += batch.length;
    }
  }

  console.log(`\n=== DONE ===`);
  console.log(`Supabase upserts: ${successCount} ✅  Errors: ${errorCount}`);
  console.log('All TS data files updated ✅');
}

applyFixes().catch(e => {
  console.error('Fatal error:', e.message);
  process.exit(1);
});
